  vals.forEach(v=>{cnt[Math.min(nb-1,Math.floor(v/bw))]++;});const pc=cnt.map(c=>c/vals.length*100),ymax=Math.max(10,Math.ceil(Math.max(...pc)/10)*10);
  const ax=axes(ctx,box,{xmin:0,xmax:hi,ymin:0,ymax,xl:'Household income in one month, Quito ($)',yl:'Share of months (%)'});
